            fetch('data/curriculum.json').then(r => { if (!r.ok) throw new Error('Curriculum load failed'); return r.json(); }),
            fetch('data/quizzes.json').then(r => { if (!r.ok) throw new Error('Quizzes load failed'); return r.json(); }),
            fetch('data/quizzes_review.json').then(r => { if (!r.ok) throw new Error('Reviews load failed'); return r.json(); }),
            fetch('data/navigation.json').then(r => { if (!r.ok) throw new Error('Navigation load failed'); return r.json(); })
